WITH parsed AS (SELECT id, service, host, level, latency_ms, payload_json, context, SHIFTRIGHT(status_code, 2) AS status_code_high, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier FROM app_logs WHERE service NOT IN ('auth', 'checkout')) SELECT level, BIT_AND(latency_ms) AS latency_ms_bit_and, SORT_ARRAY(COLLECT_SET(level)) AS level_list, PERCENTILE_APPROX(latency_ms, 0.5) AS latency_ms_p50 FROM parsed GROUP BY level
